def _owners_list_get() -> list[bytes]:
    blob = storage.get(K_OWNER_LIST)
    if not blob:
        return []
    abi.require(len(blob) % 32 == 0, b"OwnerListCorrupt")
    out: list[bytes] = []
    i = 0
    L = len(blob)
    while i < L:
        out.append(blob[i : i + 32])
        i += 32
    return out

