def _uvarint(n: int) -> bytes:
    """Unsigned varint (LE 7-bit) like protobuf/cborish style; simple and deterministic."""
    if n < 0:
        raise ValueError("uvarint cannot encode negative")
    out = bytearray()
    while True:
        b = n & 0x7F
        n >>= 7
        if n:
            out.append(0x80 | b)
        else:
            out.append(b)
            break
    return bytes(out)

