# Safe Arithmetic
# ============================================================================

def _u256(x):
    """Assert integer in uint256 range"""
    if not isinstance(x, int):
        abi.revert(b"ERR_NOT_INT")
    if x < 0 or x > UINT256_MAX:
        abi.revert(b"ERR_U256_RANGE")
    return x

def _add(a, b):
    """Checked addition"""
    a, b = _u256(a), _u256(b)
    c = a + b
    if c > UINT256_MAX:
        abi.revert(b"ERR_ADD_OVERFLOW")
    return c

def _sub(a, b):
    """Checked subtraction"""
    a, b = _u256(a), _u256(b)
    if b > a:
        abi.revert(b"ERR_SUB_UNDERFLOW")
    return a - b

def _mul(a, b):
    """Checked multiplication (with overflow)"""
    a, b = _u256(a), _u256(b)
    if a == 0 or b == 0:
        return 0
    c = a * b
    if c // a != b:
        abi.revert(b"ERR_MUL_OVERFLOW")
    return _u256(c)

def _div(a, b):
    """Safe division"""
    a, b = _u256(a), _u256(b)
    if b == 0:
        abi.revert(b"ERR_DIV_ZERO")
    return a // b

